DROP TABLE IF EXISTS `leads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `leads` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(20) NOT NULL,
  `fecha` date NOT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `ruc_dni` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `nombre` varchar(100) NOT NULL,
  `canal_id` int DEFAULT NULL,
  `contacto` varchar(100) DEFAULT NULL,
  `direccion` varchar(150) DEFAULT NULL,
  `departamento` varchar(100) DEFAULT NULL,
  `provincia` varchar(100) DEFAULT NULL,
  `distrito` varchar(100) DEFAULT NULL,
  `bien_servicio_id` int DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `comentario` text,
  `asignado_a` int DEFAULT NULL,
  `cliente_id` int DEFAULT NULL,
  `feria_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `codigo` (`codigo`),
  KEY `canal_id` (`canal_id`),
  KEY `bien_servicio_id` (`bien_servicio_id`),
  KEY `asignado_a` (`asignado_a`),
  KEY `fk_lead_cliente` (`cliente_id`),
  KEY `fk_lead_feria` (`feria_id`),
  CONSTRAINT `fk_lead_cliente` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`),
  CONSTRAINT `fk_lead_feria` FOREIGN KEY (`feria_id`) REFERENCES `marketing_ferias` (`id`) ON DELETE SET NULL,
  CONSTRAINT `leads_ibfk_1` FOREIGN KEY (`canal_id`) REFERENCES `canales_recepcion` (`id`),
  CONSTRAINT `leads_ibfk_2` FOREIGN KEY (`bien_servicio_id`) REFERENCES `bienes_servicios` (`id`),
  CONSTRAINT `leads_ibfk_3` FOREIGN KEY (`asignado_a`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4336 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
