    IF v_dni IS NULL OR v_dni = '' THEN
        SET NEW.cliente_id = NULL;
    ELSE
        SELECT id INTO v_cliente_id
        FROM clientes
        WHERE TRIM(REPLACE(ruc_dni,' ','')) = v_dni
        LIMIT 1;

        IF v_cliente_id IS NOT NULL THEN
            
            UPDATE clientes
            SET 
                nombre       = IF(NEW.nombre IS NOT NULL AND NEW.nombre <> '', NEW.nombre, nombre),
                telefono     = IF(NEW.telefono IS NOT NULL AND NEW.telefono <> '', NEW.telefono, telefono),
                contacto     = IF(NEW.contacto IS NOT NULL AND NEW.contacto <> '', NEW.contacto, contacto),
                direccion    = IF(NEW.direccion IS NOT NULL AND NEW.direccion <> '', NEW.direccion, direccion),
                departamento = IF(NEW.departamento IS NOT NULL AND NEW.departamento <> '', NEW.departamento, departamento),
                provincia    = IF(NEW.provincia IS NOT NULL AND NEW.provincia <> '', NEW.provincia, provincia),
                distrito     = IF(NEW.distrito IS NOT NULL AND NEW.distrito <> '', NEW.distrito, distrito),
                email        = IF(NEW.email IS NOT NULL AND NEW.email <> '', NEW.email, email)
            WHERE id = v_cliente_id;

        ELSE
            INSERT INTO clientes (
                ruc_dni, nombre, telefono, contacto, direccion,
                departamento, provincia, distrito, email
            )
            VALUES (
                NEW.ruc_dni, NEW.nombre, NEW.telefono, NEW.contacto,
                NEW.direccion, NEW.departamento, NEW.provincia,
                NEW.distrito, NEW.email
            );

            SET v_cliente_id = LAST_INSERT_ID();
        END IF;

        SET NEW.cliente_id = v_cliente_id;
    END IF;
END */;;
DELIMITER ;
