/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `after_seguimiento_cerrado` AFTER INSERT ON `seguimientos` FOR EACH ROW BEGIN
    -- Solo si el proceso es "Cerrado" (proceso_id = 5)
    IF NEW.proceso_id = 5 THEN
        -- Insertar en ventas_concretadas solo si no existe ya para este lead
        INSERT INTO ventas_concretadas (
            cliente_id,
            lead_id,
            bien_servicio_id,
            monto,
            fecha_venta
        )
        SELECT
            l.cliente_id,
            l.id,
            l.bien_servicio_id,
            NEW.monto,
            NEW.fecha_guardado
        FROM leads l
        WHERE l.id = NEW.lead_id
        AND NOT EXISTS (
            SELECT 1
            FROM ventas_concretadas vc
            WHERE vc.lead_id = NEW.lead_id
        )
        LIMIT 1;
    END IF;
END */;;
DELIMITER ;
